import java.util.*;

class MedianFinder {
    private final PriorityQueue<Integer> lower = new PriorityQueue<>(Collections.reverseOrder());
    private final PriorityQueue<Integer> upper = new PriorityQueue<>();

    public MedianFinder() {
    }

    public void addNum(int num) {
        lower.offer(num);
        upper.offer(lower.poll());
        if (upper.size() > lower.size()) {
            lower.offer(upper.poll());
        }
    }

    public double findMedian() {
        if (lower.size() > upper.size()) {
            return lower.peek();
        }
        return lower.peek() / 2.0 + upper.peek() / 2.0;
    }
}

import java.util.*;

class MedianFinder {
    private final List<Integer> sorted = new ArrayList<>();

    public MedianFinder() {
    }

    public void addNum(int num) {
        int index = Collections.binarySearch(sorted, num);
        if (index < 0) {
            index = -index - 1;
        }
        sorted.add(index, num);
    }

    public double findMedian() {
        int size = sorted.size();
        if (size % 2 == 1) {
            return sorted.get(size / 2);
        }
        int left = sorted.get(size / 2 - 1);
        int right = sorted.get(size / 2);
        return left / 2.0 + right / 2.0;
    }
}

import java.util.*;

class MedianFinder {
    private final TreeMap<Integer, Integer> counts = new TreeMap<>();
    private int size = 0;

    public MedianFinder() {
    }

    public void addNum(int num) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
        size++;
    }

    public double findMedian() {
        if (size % 2 == 1) {
            return kth(size / 2 + 1);
        }
        int left = kth(size / 2);
        int right = kth(size / 2 + 1);
        return left / 2.0 + right / 2.0;
    }

    private int kth(int rank) {
        int seen = 0;
        for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
            seen += entry.getValue();
            if (seen >= rank) {
                return entry.getKey();
            }
        }
        throw new IllegalStateException("Median is undefined for an empty stream");
    }
}

class MedianFinder {
    private static final int OFFSET = 100000;
    private static final int SIZE = 200001;
    private final int[] tree = new int[SIZE + 1];
    private int count = 0;

    public MedianFinder() {
    }

    public void addNum(int num) {
        add(num + OFFSET + 1, 1);
        count++;
    }

    public double findMedian() {
        if (count % 2 == 1) {
            return valueAtRank(count / 2 + 1);
        }
        int left = valueAtRank(count / 2);
        int right = valueAtRank(count / 2 + 1);
        return left / 2.0 + right / 2.0;
    }

    private void add(int index, int delta) {
        while (index <= SIZE) {
            tree[index] += delta;
            index += index & -index;
        }
    }

    private int valueAtRank(int rank) {
        int index = 0;
        int bit = Integer.highestOneBit(SIZE);
        while (bit != 0) {
            int next = index + bit;
            if (next <= SIZE && tree[next] < rank) {
                index = next;
                rank -= tree[next];
            }
            bit >>= 1;
        }
        return index + 1 - OFFSET - 1;
    }
}
